insert into learn_review_items (
  entity_type, entity_ref, location, claim, category, severity, status, source_hint, notes
) values (
  'QUESTION', 'question:sq-i1-06', 'Intermediate · Stage 1, How Donation Happens: The Process · Stage Quiz', 'In determining circulatory death, why must circulation and breathing be absent for five continuous minutes?',
  'LEGAL', 2, 'APPROVED',
  'Thomson D, et al. South African guidelines on the determination of death. S Afr J Crit Care 2021;37(1b):41-54, §4: death on circulatory grounds requires that CPR is inappropriate, has failed, or that life-sustaining treatment has been withdrawn; observation for a minimum of five minutes ''to establish that irreversible circulatory arrest has occurred''; any spontaneous return of circulatory or respiratory activity during the five minutes resets the observation period, and is not an indication to begin resuscitation where that has been judged inappropriate; afterwards, absent pupillary responses to light and absent motor response to supra-orbital pressure are confirmed, and the time of death recorded; no intervention with the potential to restore cerebral perfusion may be initiated after death is confirmed; where DCD takes place a second doctor certifies death, one with more than five years'' experience and neither involved with the transplant team (Fig. 4)', 'Keyed answer and explanation checked against: Thomson D, et al. South African guidelines on the determination of death. S Afr J Crit Care 2021;37(1b):41-54, §4: death on circulatory grounds requires that CPR is inappropriate, has failed, or that life-sustaining treatment has been withdrawn; observation for a minimum of five minutes ''to establish that irreversible circulatory arrest has occurred''; any spontaneous return of circulatory or respiratory activity during the five minutes resets the observation period, and is not an indication to begin resuscitation where that has been judged inappropriate; afterwards, absent pupillary responses to light and absent motor response to supra-orbital pressure are confirmed, and the time of death recorded; no intervention with the potential to restore cerebral perfusion may be initiated after death is confirmed; where DCD takes place a second doctor certifies death, one with more than five years'' experience and neither involved with the transplant team (Fig. 4)'
